palettes.customCss:
/* enlarge top bar text and score text */
.riddle .top-bar .pager .pager-text, .riddle .live-score .pill__scoreText {
    font-size: 1.5rem;
}

.riddle:not(.block-type-Swiper):not(.block-type-SpotTheDifference):not(.block-type-TapAndFind).has-media .top-bar .pager {

    --color-top-bar-media-bg: white;
    --color-top-bar-media-text: black;
}

.riddle .image-embed::after {
    content: 'Daily PM quiz';
    position: absolute;
    display: flex;
    justify-content: center;
    align-items: center;
    bottom: 0;
    left: 0;
    right: 0;
    text-align: center;
    background: #D7CAF4;
    color: #7D59C9;
    text-transform: uppercase;
    font-size: 1.3rem;
    height: 20px;
    z-index: 99;
}

.riddle .choice .image-embed::after {
    content: none;
}

.riddle .live-score svg {
    width: 14px;
    height: 14px;
}
/* remove image attribition */
.riddle .block .attribution, .riddle a.attribution {
    display: none ;
}


/* remove 'More Information' */
.riddle [data-test="answer-explanation"] .icon {
   display: none !important; 
}
.riddle [data-test="answer-explanation"] > h2:first-of-type {
   display: none !important; 
}


.riddle .choices .choice .choice-content .voting-result .voting-result-inner {
    font-size: 1.3rem;
    font-weight: 600;
}

/*.riddle .correct-wrong-banner-wrapper {*/
/*    display: none !important;*/
/*}*/

.riddle .choices {
    --color-answer-selected-bg: rgba(0, 0, 0, 0);
    --color-choice-bg: rgba(0, 0, 0, 0);
}

.riddle .choice.is-selected:has(.is-wrong-answer) {
    outline-color: #C70000;

}

.riddle .choice.is-selected:has(.is-correct-answer) {
    outline-color: #058E1E;

}

.riddle .choice.is-selected .percentage-bar-wrapper:has(.wrong) {
    background-color: #FFEBEB;
}

.riddle .choice.is-selected .percentage-bar-wrapper:has(.correct) {
    background-color: #DDFADB;
}

.riddle .choice.is-selected .voting-result-inner:has(.percent.wrong.only) {
    background-color: #C70000;
    color: white;
}

.riddle .choice.is-selected .voting-result-inner:has(.percent.correct.only) {
    background-color: #058E1E;
    color: white;
}

/* right answer - not selected */
.riddle .choice .voting-result-inner:has(.percent.correct.only) {
    background-color: #DDFADB;
    border-color: #058E1E;
    color: #058E1E;

}


.riddle .btn:hover, .btn:focus, .btn:active {
    transform: scale(1.05);
}

.riddle .answer-explanation {
    background-color: white !important;
}
.riddle .first-row  {
    --color-top-bar-media-bg: #636363 ;
}
.riddle .live-score .pill {
    background-color: var(--color-top-bar-media-bg);
}

.riddle .explanation-btn {
    background-color: white;
    color: #8D1DE8;
    border: 1px solid #8D1DE8;
}

.riddle .explanation-wrapper__navigation>.btn {
    background-color: white;
    color: #8D1DE8;
    border: 1px solid #8D1DE8;
}

.riddle .block-wrapper[data-type='Media'] {
    position: relative;

}
.riddle .block-wrapper[data-type='Media'] div:first-child{
    aspect-ratio:16 / 9;

}
.riddle .block-wrapper[data-type='ResultScore'] {
    position: absolute;
    top: 10px;
    right: 10px;

}

.riddle .block[data-block-type-group="Result"] .top-bar {
    display:none;
}


.riddle svg .score {
    fill: #8D1DE8;
    font-size: 5rem !important;
}
/*.riddle svg g[data-v-72c8c293] {*/
/*    transform: translateY(-10px);*/
/*}*/

.riddle svg text.max-score {
    --color-text: #939393;
    color: #939393;
    fill: #939393;
    font-size: 3rem !important;
    font-weight: 500 !important;
    transform: translateY(-15px);
}

/*.riddle svg .circle-bg, .riddle svg .circle-highlight {*/
    /*stroke-width: 12px;*/
/*}*/
.riddle svg line {
    stroke-width: 2px !important;
    transform: translateY(-10px) !important;
    stroke: #939393;
}


.riddle svg circle {
    fill: transparent;
}

/*circle score backgroud */
/*.riddle svg circle.circle-bg {*/
/*    fill: rgba(0, 0, 0, .3) !important;*/
/*}*/

.riddle svg.circle-svg {
    outline: 2px solid white;
    border-radius: 50%;
}

.riddle svg .circle-highlight {
    stroke: #A343F7 !important;
}

.riddle svg circle.bg {
    fill: rgba(255, 255, 255, .8);
}

.riddle .page {
    padding-bottom: 0 !important;
}

.riddle .replay-btn {
    background-color: white !important;
    --color-btn-text: #8D1DE8;
    border: 1px solid #8D1DE8 !important;
    border-radius: 40px !important;
    text-transform: none !important;
    font-size: 2rem !important;
    padding: 30px 40px !important;
    margin-top: 24px;
    width: 300px;
}

.riddle .networks-list .share-button {
    background-color: #A343F7 !important;
}

.riddle .networks-list .share-button:hover {
    background-color: #D1A3FF !important;

}
.riddle .choices:not(.order).fixed-height {
    overflow: auto;
}

@media (max-width:410px){
    .riddle .result-score-inner {
        transform: scale(.75);
    }
    .riddle a.button,.riddle .replay-btn {
        padding: 20px 30px;
    }
}

@media (max-width: 520px) {
    .riddle .share-block  {
        padding-top: 20px;
    }
}
